-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.paladin.holy.Name"] = "Sagrado"
L["rm.era.paladin.holy.Description"] = "Cura em grupo com a árvore Sagrado, a partir do nível 10. Age sobre seu alvo amigável e escolhe a cura pela vida que falta: Purificação ou Purificar, Choque Sagrado enquanto você se move, Luz Sagrada de grau máximo abaixo de 40%, Luz Sagrada grau 6 abaixo de 65%, Clarão de Luz de grau máximo abaixo de 85%, Clarão de Luz grau 4 abaixo de 95%. Com um inimigo ao alcance corpo a corpo: Selo da Sabedoria e, fora de raides, Julgamento. Lembretes: Aura de Concentração ou Aura de Devoção, Bênção de Sabedoria, Favorecimento Divino e Impor as Mãos para um alvo com muito pouca vida. A escolha de quem curar fica com você; Paladinos Sagrados jogando solo recebem a rotação integrada de Retribuição."
L["rm.era.paladin.protection.Name"] = "Proteção"
L["rm.era.paladin.protection.Description"] = "Tanque do nível 1 ao 60, escolhida por Fúria Íntegra ou pela árvore Proteção. Selo da Retidão (Selo da Sabedoria quando a mana cai abaixo de 40%), Escudo Sagrado e Julgamento para puxar, Escudo Sagrado mantido, Consagração e Ira Sagrada (Mortos-vivos e Demônios) quando dois ou mais inimigos estiverem em você, senão Julgamento do Cruzado uma vez, depois Julgamento e Consagração com mana de sobra, Exorcismo em Mortos-vivos e Demônios. Lembretes: Fúria Íntegra, Aura de Devoção, Santuário, Reis ou Poder, Impor as Mãos quando estiver quase morto. Provocar, o uso repetido de Bênção dos Reis e os graus dos feitiços ficam com você."
L["rm.era.paladin.protection.icyveins.Name"] = "Proteção, Selo da Sabedoria (Icy Veins)"
L["rm.era.paladin.protection.icyveins.Description"] = "O tanque de raide da Icy Veins com a rotação de Sabedoria da Wowhead, uma alternativa à rotação integrada de Proteção recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Mantém Selo da Sabedoria ativo e o julga sempre que o alvo estiver sem Julgamento da Sabedoria, senão julga só para puxar; Escudo Sagrado, Consagração a cada recarga, Ira Sagrada em grupos de Mortos-vivos e Demônios, Exorcismo e Bênção Maior dos Reis como preenchimento de ameaça em raide. Os mesmos lembretes da rotação integrada recomendada."
L["rm.era.paladin.retribution.Name"] = "Retribuição"
L["rm.era.paladin.retribution.Description"] = "Retribuição corpo a corpo do nível 1 ao 60, e o padrão para qualquer Paladino em que nenhuma outra rotação integrada se encaixe. Em elites e lutas longas fora de raides, ativa Selo do Cruzado e o julga uma vez; nos demais casos, mantém um selo ativo (Comando com uma arma de 3,5 segundos ou mais lenta, senão Retidão), Exorcismo e Ira Sagrada em Mortos-vivos e Demônios, Martelo da Ira, Julgamento assim que sair do tempo de recarga, Consagração enquanto Vingança estiver ativa ou contra dois ou mais inimigos próximos. Lembretes: Aura de Santidade, Aura da Retribuição ou Aura de Devoção, Bênção de Sabedoria solo ou Bênção do Poder em grupo, uma cura entre os combates, Escudo Divino, Proteção Divina ou Impor as Mãos quando você estiver prestes a morrer. A alternância de selos é uma rotação integrada separada; a escolha de alvo e o posicionamento ficam com você."
L["rm.era.paladin.retribution.twist.Name"] = "Retribuição com alternância de selos"
L["rm.era.paladin.retribution.twist.Description"] = "Desativada por padrão; ative-a se você alterna selos. Para um Paladino de Retribuição com Selo de Comando: mantém Selo da Retidão ativo, troca para Selo de Comando grau 1 nos últimos 0,4 segundos antes de um golpe e volta de novo, Julgamento sempre que estiver pronto, Exorcismo e Ira Sagrada em Mortos-vivos e Demônios, Martelo da Ira, Consagração com Vingança. Exige muita mana e um bom timing. Os mesmos lembretes da rotação integrada de Retribuição."
L["rm.forever.paladin.holy.Name"] = "Sagrado"
L["rm.forever.paladin.holy.Description"] = "Cura em grupo assim que Sagrado é sua árvore de talentos principal com 21 pontos (o nível do Choque Sagrado), enquanto Fúria Íntegra está desativada (um Shockadin em grupo também cai aqui). Cura seu alvo amigável atual: Choque Sagrado em um alvo com sua Luz Zelosa, Luz Zelosa em combate, Purificação ou Purificar, Choque Sagrado em movimento, Luz Sagrada com Infusão de Luz, Clarão de Luz como cura principal. Em um inimigo: Julgamento da Luz quando Selo da Luz está ativo, Choque Sagrado, Luz Zelosa, Golpe Sagrado, Exorcismo. Lembretes: Selo da Luz quando você não tem selo, Favorecimento Divino em combate em um alvo amigável, sua aura e Bênção. A vida e a mana ficam ocultas dos addons no Forever, então o alvo que você escolhe é o único sinal de quem precisa de cura; Choques Sagrados de emergência, Luzes Sagradas grandes e Impor as Mãos são decisões suas."
L["rm.forever.paladin.holy.wowhead.Name"] = "Sagrado, Choque Sagrado sempre disponível (Wowhead)"
L["rm.forever.paladin.holy.wowhead.Description"] = "O estilo de cura da Wowhead, uma alternativa à rotação integrada de Sagrado recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Choque Sagrado como cura de rotina sempre que sair do tempo de recarga, dissipações, Clarão de Luz (a vida fica oculta no Forever, então Luz Sagrada para grandes perdas de vida é decisão sua). Em um inimigo, mantém seu Julgamento da Luz trocando para Selo da Luz, julgando e voltando para Selo da Retidão, depois Golpe Sagrado, Exorcismo em Mortos-vivos e Demônios, Choque Sagrado e Consagração. Os mesmos lembretes da rotação integrada de Sagrado."
L["rm.forever.paladin.protection.Name"] = "Proteção (Wowhead)"
L["rm.forever.paladin.protection.Description"] = "Tanque, assim que Proteção é sua árvore de talentos principal ou você ativa Fúria Íntegra. Quando o alvo está lutando com outra pessoa: Julgamento com Selo da Fúria (a provocação), Julgamento Célere para reiniciá-lo. Dois ou mais inimigos em combate: Consagração, Exorcismo e Ira Sagrada em Mortos-vivos e Demônios, Golpe Sagrado. Um inimigo: Exorcismo em Mortos-vivos e Demônios, Golpe Sagrado, Consagração. Lembretes: Fúria Íntegra, Selo da Fúria, Julgamento sempre que sair do tempo de recarga, Escudo Sagrado enquanto tanqueia, sua aura e Bênção. A vida e a mana ficam ocultas dos addons no Forever, então Baluarte do Templário e Impor as Mãos são decisões suas. Puxar, posicionamento e outras provocações ficam com você."
L["rm.forever.paladin.protection.icyveins.Name"] = "Proteção, Consagração primeiro (Icy Veins)"
L["rm.forever.paladin.protection.icyveins.Description"] = "O estilo de tanque da Icy Veins, uma alternativa à rotação integrada de Proteção da Wowhead recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Consagração primeiro sempre que você puder pagar por ela, também contra um só inimigo; Julgamento fica reservado para provocações (sem lembrete de tempo de recarga), com Julgamento Célere para reiniciá-lo; depois Golpe Sagrado e Exorcismo em Mortos-vivos e Demônios. No resto, os mesmos lembretes de tanque."
L["rm.forever.paladin.retribution.Name"] = "Retribuição"
L["rm.forever.paladin.retribution.Description"] = "Retribuição e todo Paladino corpo a corpo do nível 1 ao 60, e o padrão do Paladino no Forever. Mantém um selo de dano ativo, renovado só quando está acabando: Selo do Cruzado julgado uma vez em um alvo de elite, depois Selo de Comando com uma arma lenta (3,0 s), senão Selo da Retidão. Depois Golpe Sagrado sempre que sair do tempo de recarga, Choque Sagrado e Luz Zelosa para um Shockadin, Exorcismo em Mortos-vivos e Demônios, Consagração em três ou mais inimigos, Martelo da Ira quando puder ser lançado, e corpo a corpo. Julgamento não usa o tempo de recarga global, então é um lembrete sempre que um selo está ativo. Outros lembretes: sua aura e Bênção (Aura da Retribuição e Reis depois de aprendidas; as suas são mantidas). Passo opcional, desativado por padrão: Martelo da Justiça antes de um Julgamento do Selo de Comando. A mana, a vida e o tempo de golpe ficam ocultos dos addons no Forever, então economizar mana, se curar, Impor as Mãos e a troca de selos com Torção de Luz são decisões suas. Montada a partir de guias do beta de nível 30."
L["rm.mop.paladin.holy.Name"] = "Recomendada"
L["rm.mop.paladin.holy.Description"] = "Para Sagrado, a partir do nível 10 na especialização Sagrado. Com um aliado selecionado, cura: com 3 de Poder Sagrado (ou Desígnio Divino), Luz da Aurora quando três pessoas perto de você estiverem feridas, senão Chama Eterna em um alvo sem ela, senão Palavra de Glória; Choque Sagrado assim que sair do tempo de recarga; Infusão de Luz em Resplendor Sagrado ou Luz Divina, três acúmulos de Curador Abnegado em Resplendor Sagrado ou Clarão de Luz; Clarão de Luz abaixo de 35%; Resplendor Sagrado para um grupo ferido; Luz Divina, depois Luz Sagrada para completar. Com um inimigo selecionado, causa dano: Choque Sagrado, Julgamento, Golpe do Cruzado, Prisma Sagrado, Pena de Morte, Martelo da Ira, Condenar. Lembretes: Selo da Intuição quando outro selo (exceto Retidão) ou nenhum estiver ativo, bênçãos, Repreensão, Foco de Luz e Escudo Sagrado no seu foco (defina o tanque como foco), Apelo Divino abaixo de 60% de mana, Martelo da Luz e seus tempos de recarga de cura quando três pessoas estiverem abaixo de 70%, Impor as Mãos em um alvo morrendo. A escolha de quem curar, dissipações e cura com mouseover ficam com você."
L["rm.mop.paladin.protection.Name"] = "Recomendada"
L["rm.mop.paladin.protection.Description"] = "Recomendada para Proteção, a partir do nível 10 na especialização Proteção. Puxa com Escudo do Vingador, depois Escudo do Vingador com uma ativação de Grande Cruzado, Escudo do Vingador, Martelo da Ira, Golpe do Cruzado, Julgamento, seu talento de nível 90, Consagração, Ira Sagrada e Escudo Sagrado. Três ou mais inimigos em você trocam para Escudo do Vingador, Consagração, Martelo do Íntegro, Julgamento e Ira Sagrada. Escudo do Íntegro, Chama Eterna e Palavra de Glória estão fora do tempo de recarga global, então acendem ao lado da rotação: Escudo do Íntegro sempre que você puder pagá-lo, Chama Eterna em você mesmo quando estiver acabando, com 3 de Poder Sagrado e três acúmulos de Bastião de Glória, Palavra de Glória abaixo de metade da vida sem esse talento. Outros lembretes: Fúria Íntegra, Selo da Intuição quando outro selo (exceto Retidão) ou nenhum estiver ativo, bênçãos, Repreensão, Escudo Sagrado, Ira Vingativa e Vingador Sagrado enquanto você tanqueia, e Guardião dos Reis Antigos, Defensor Ardente, Proteção Divina e Impor as Mãos conforme sua vida. Ela não consegue ver o dano que está chegando, então planeje você mesmo as grandes defesas."
L["rm.mop.paladin.protection.simulator.Name"] = "Acumular Poder Sagrado (simulador)"
L["rm.mop.paladin.protection.simulator.Description"] = "Uma alternativa à rotação integrada recomendada de Proteção, desativada por padrão: ative esta e desative aquela, ou aumente a prioridade desta. Segue as listas de tanque do simulador: Escudo do Íntegro espera Poder Sagrado cheio, a menos que você caia abaixo de 40% de vida ou Desígnio Divino o torne gratuito; Chama Eterna pouco antes de expirar com mais de dois acúmulos de Bastião de Glória; Escudo Sagrado mantido; Vingador Sagrado e Ira Vingativa assim que saírem do tempo de recarga. Os geradores seguem Golpe do Cruzado, Julgamento, depois Escudo do Vingador, Ira Sagrada, o talento de nível 90 e Martelo da Ira, com a mesma ordem de dano em área para três inimigos. As defesas sincronizadas com o chefe ficam com você."
L["rm.mop.paladin.retribution.Name"] = "Recomendada"
L["rm.mop.paladin.retribution.Description"] = "Recomendada para Retribuição, a partir do nível 10 na especialização Retribuição. Mantém Inquisição ativa (lançada com 3 de Poder Sagrado, renovada nos seus últimos 3 segundos; a partir do nível 81), gasta Veredito do Templário com Poder Sagrado cheio ou com uma ativação gratuita antes de gerar mais, depois Martelo da Ira, Golpe do Cruzado, Julgamento e Exorcismo, e Veredito do Templário com 3 quando nada mais estiver pronto. Durante Ira Vingativa, gasta na hora e põe Julgamento à frente de Golpe do Cruzado. Dois ou mais inimigos em você trocam para Tempestade Divina, com Martelo do Íntegro quando quatro estiverem perto. Puxa à distância com Julgamento ou Exorcismo, e sugere Palavra de Glória quando você está solo e em perigo. Lembretes: Selo da Verdade quando outro selo estiver ativo ou nenhum (Selo da Retidão é mantido), Bênção dos Reis ou Bênção do Poder, Repreensão, Ira Vingativa e Guardião dos Reis Antigos com Inquisição ativa em elites, Vingador Sagrado durante Ira Vingativa, Pena de Morte e Martelo da Luz, e Proteção Divina e Impor as Mãos com pouca vida. Selo da Retidão para grupos de inimigos e as escolhas de glifos ficam com você."
L["rm.mop.paladin.retribution.warcrafttavern.Name"] = "Exorcismo primeiro (Warcraft Tavern)"
L["rm.mop.paladin.retribution.warcrafttavern.Description"] = "Uma alternativa à rotação integrada recomendada de Retribuição, desativada por padrão: ative esta e desative aquela, ou aumente a prioridade desta. Exorcismo a cada recarga e a cada reinício de A Arte da Guerra vem primeiro; Inquisição é lançada com qualquer Poder Sagrado quando estiver ausente e renovada com 3 nos seus últimos 20 segundos; depois Golpe do Cruzado, Julgamento, Veredito do Templário e Martelo da Ira (primeiro durante Ira Vingativa com Ira Santificada). Dois ou mais inimigos usam Golpe do Cruzado, Martelo da Luz, Julgamento, Tempestade Divina e Martelo da Ira. Ira Vingativa e Guardião dos Reis Antigos só são sugeridos em elites. O Selo da Retidão do guia em qualquer situação de dano em área fica com você."
L["rm.mop.paladin.unspecialized.Name"] = "Antes de uma especialização"
L["rm.mop.paladin.unspecialized.Description"] = "Para os níveis 1 a 9, e qualquer paladino que ainda não escolheu uma especialização; a rotação integrada de uma especialização assume assim que você escolhe uma. Puxa à distância com Julgamento, depois Golpe do Cruzado e Julgamento, com Martelo da Justiça quando você está solo e abaixo de metade da vida e Palavra de Glória abaixo de 40%. Lembretes: Selo de Comando (Selo da Verdade a partir do nível 24) quando você não estiver nele, Bênção dos Reis, Repreensão, e Clarão de Luz fora de combate quando você estiver ferido."
L["rm.retail.paladin.holy.Name"] = "Icy Veins"
L["rm.retail.paladin.holy.Description"] = "Sagrado no Midnight, como referência: o Rotation Master escolhe um feitiço, não um alvo, e o jogo oculta a vida de todos em combate, então esta rotação mantém seu Poder Sagrado e seus tempos de recarga girando em qualquer alvo que você selecionar e deixa com você a decisão de quem precisa de cura. O Poder Sagrado continua visível em combate, então é gasto primeiro com 5 e, depois das suas outras curas, com 3 ou mais. Em um alvo amigável: Chama Eterna ou Palavra de Glória com 5 de Poder Sagrado, Clarão de Luz com Infusão de Luz, Choque Sagrado, Chama Eterna ou Palavra de Glória com 3 ou mais, Luz Sagrada, Clarão de Luz; Luz da Aurora fica com você. Em um inimigo: Escudo do Íntegro com 5 de Poder Sagrado, Choque Sagrado, Escudo do Íntegro com 3 ou mais, Julgamento, Golpe do Cruzado, Consagração. Lembretes em combate: Preço Divino, Prisma Sagrado, Baluarte Sagrado ou Arma Sagrada, Foco de Virtude em um alvo amigável, Proteção Divina; uma aura entre os combates; Repreensão. Impor as Mãos fica com você. Ira Vingativa e Proficiência em Auras ficam com você."
L["rm.retail.paladin.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.paladin.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Paladino). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Paladino compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.retail.paladin.protection.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.paladin.protection.Description"] = "Recomendada para Proteção no Midnight. Mostra a sugestão do Assistente de Combate da Blizzard, que já inclui Escudo do Íntegro, Ira Vingativa e Sentinela, e para enquanto você lança ou não tem um inimigo como alvo. Lembretes do que ela deixa de fora: uma aura entre os combates, Repreensão em um lançamento interrompível, e Defensor Ardente e Guardião dos Reis Antigos sempre que estiverem prontos em combate. A vida fica oculta no Retail, então decidir quando usá-los, e Impor as Mãos, é com você. Provocações e posicionamento ficam com você."
L["rm.retail.paladin.protection.icyveins.Name"] = "Referência (Icy Veins)"
L["rm.retail.paladin.protection.icyveins.Description"] = "Apenas referência, desativada por padrão: a ordem da Icy Veins e do SimulationCraft precisa dos bônus de Consagração, Vanguarda e Luz Rutilante, que o Midnight oculta em combate. Consagração antes da puxada; depois Preço Divino, Martelo de Luz, Consagração quando você não estiver sobre ela, Escudo do Vingador com Vanguarda, Escudo do Íntegro com 3 ou mais de Poder Sagrado, Martelo da Ira, Julgamento, Martelo Abençoado ou Martelo do Íntegro, Escudo do Vingador, Palavra de Glória com Luz Rutilante, Consagração. Lembretes: Ira Vingativa ou Sentinela, Baluarte Sagrado, Arma Sagrada fora de Ira Vingativa, defesas, aura, Repreensão."
L["rm.retail.paladin.protection.wowhead.Name"] = "Referência de preenchimento com Consagração (Wowhead)"
L["rm.retail.paladin.protection.wowhead.Description"] = "Apenas referência, desativada por padrão: a ordem de tanque da Wowhead. Julgamento assim que sair do tempo de recarga, Escudo do Íntegro, Escudo do Vingador, Preço Divino com 0 de Poder Sagrado, Martelo Abençoado ou Martelo do Íntegro e Consagração só como preenchimento. A vida fica oculta no Retail, então Palavra de Glória abaixo de metade da vida fica com você. Os mesmos lembretes da referência da Icy Veins."
L["rm.retail.paladin.retribution.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.paladin.retribution.Description"] = "Recomendada para Retribuição no Midnight. Em combate, o jogo agora oculta bônus, penalidades, tempos de recarga e vida para addons, então esta rotação mostra a própria sugestão do Assistente de Combate da Blizzard (a rotação de um botão) nas suas barras de ações, e para enquanto você lança ou não tem um inimigo como alvo. Ela também lembra você do que essa sugestão nunca cobre: uma aura entre os combates, Repreensão em um lançamento interrompível, e Proteção Divina sempre que estiver pronta em combate. A vida fica oculta no Retail, então decidir quando usar Proteção Divina e Impor as Mãos é com você. Berloques e habilidades raciais ficam com você."
L["rm.retail.paladin.retribution.icyveins.Name"] = "Referência (Icy Veins)"
L["rm.retail.paladin.retribution.icyveins.Description"] = "Apenas referência, desativada por padrão: a ordem da Icy Veins e do SimulationCraft lê bônus, cargas e número de inimigos que o Midnight oculta em combate, então ela não pode funcionar de forma confiável lá. Martelo de Luz; um gasto gratuito com Desígnio Divino; com 5 de Poder Sagrado enquanto Rastro de Cinzas está em recarga, o gasto; Rastro de Cinzas; Preço Divino; Lâmina da Justiça com Arte da Guerra; Martelo da Ira antes de chegar ao limite de cargas; com 3 ou mais de Poder Sagrado, Tempestade Divina contra dois ou mais inimigos (ou com Poder Empíreo), senão Veredito Final; Martelo da Ira; Lâmina da Justiça; Julgamento; Golpe Templário ou Golpe do Cruzado. O Poder Sagrado continua visível em combate, então os pontos de gasto dele funcionam lá. Lembretes: Ira Vingativa, Pena de Morte com Rastro de Cinzas pronto, aura, Repreensão, defesas."
L["rm.sod.paladin.holy.Name"] = "Sagrado (SoD)"
L["rm.sod.paladin.holy.Description"] = "Cura em grupo da Temporada da Descoberta, escolhida por Foco de Luz, Luz Divina ou Escudo Sagrado gravados, ou pela árvore Sagrado sem Golpe do Cruzado. Age sobre seu alvo amigável: Purificação, Choque Sagrado em movimento ou abaixo de 30%, Luz Divina (Luz Sagrada quando a mana estiver abaixo da metade) abaixo de 60%, Clarão de Luz abaixo de 90%. Com um inimigo ao alcance corpo a corpo, só mantém um selo ativo. Lembretes: Foco de Luz e Escudo Sagrado no alvo que não os tiver, Aura de Concentração ou Aura de Devoção, Bênção de Sabedoria, Favorecimento Divino e Impor as Mãos para um alvo com muito pouca vida. Os guias por trás dela são da Fase 4; a escolha de quem curar fica com você."
L["rm.sod.paladin.holy.wowhead.Name"] = "Sagrado, Luz Sagrada primeiro (SoD, Wowhead)"
L["rm.sod.paladin.holy.wowhead.Description"] = "A ordem de cura da Fase 4 da Wowhead para equipamento com muito crítico, uma alternativa à rotação integrada de Sagrado da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Luz Divina ou Luz Sagrada abaixo de 75%, depois Purificação, Choque Sagrado para pequenas perdas de vida ou em movimento, Clarão de Luz abaixo de 95%. Os mesmos lembretes da rotação integrada recomendada."
L["rm.sod.paladin.protection.Name"] = "Proteção (SoD)"
L["rm.sod.paladin.protection.Description"] = "Tanque da Temporada da Descoberta, escolhida por Fúria Íntegra, por Martelo do Íntegro ou Escudo de Retidão gravados, ou pela árvore Proteção. Selo do Martírio, uma puxada com Escudo Sagrado, Escudo do Vingador e Exorcismo, Escudo Sagrado mantido; contra um alvo, Martelo do Íntegro, Escudo de Retidão, Exorcismo, Escudo do Vingador, Julgamento, Tempestade Divina, Consagração; com três ou mais inimigos em você, Martelo do Íntegro, Escudo do Vingador, Consagração, Escudo de Retidão, Exorcismo. Lembretes: Fúria Íntegra, Escudo Sagrado antes de puxar, Aura de Devoção, Santuário ou Reis, Ira Vingativa, Proteção Divina abaixo de 40%, Impor as Mãos, Ato de Bravura em grupo quando seu alvo ataca outra pessoa."
L["rm.sod.paladin.protection.simulator.Name"] = "Proteção (SoD, simulador)"
L["rm.sod.paladin.protection.simulator.Description"] = "A lista de tanque do simulador, uma alternativa à rotação integrada de Proteção da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Julgamento sempre que um selo estiver ativo, o selo renovado pouco antes de acabar, Escudo Sagrado, Escudo do Vingador, Martelo do Íntegro, Exorcismo, Escudo de Retidão por último. Os mesmos lembretes da rotação integrada recomendada."
L["rm.sod.paladin.retribution.Name"] = "Retribuição (SoD)"
L["rm.sod.paladin.retribution.Description"] = "Corpo a corpo da Temporada da Descoberta do nível 1 ao 60, e o padrão para qualquer Paladino lá. Mantém Selo do Martírio ativo (Retidão até você tê-lo), abre com Exorcismo, lança Tempestade Divina com três de Poder Sagrado, depois conforme a velocidade da arma: com uma arma de duas mãos de 3,3 segundos ou mais lenta, Golpe do Cruzado, Exorcismo, Tempestade Divina e Julgamento; com uma mais rápida, Julgamento só quando o selo estiver acabando, depois Exorcismo, Golpe do Cruzado e Tempestade Divina. Consagração com mana ou três inimigos próximos, Ira Sagrada em Mortos-vivos e Demônios (em qualquer alvo com Poder Purificador gravado), Martelo da Ira com mana de sobra (sempre com Martelo da Ira Aprimorado gravado). As runas são usadas conforme você as grava. Lembretes: Aura de Santidade, uma Bênção, Ira Vingativa com Proficiência em Auras, uma cura entre os combates, Escudo Divino quando estiver prestes a morrer."
L["rm.sod.paladin.retribution.icyveins.Name"] = "Retribuição (SoD, Icy Veins Fase 4)"
L["rm.sod.paladin.retribution.icyveins.Description"] = "A lista mais antiga da Fase 4 da Icy Veins e da Warcraft Tavern, também boa para evoluir de nível, uma alternativa à rotação integrada recomendada de Retribuição da Temporada da Descoberta, desativada por padrão: ative esta e desative aquela, ou aumente a prioridade desta. Julgamento do Cruzado uma vez em elites e lutas longas, Selo do Martírio, Exorcismo, Golpe do Cruzado, Tempestade Divina e Julgamento assim que saírem do tempo de recarga, Consagração com mana ou três inimigos próximos, Martelo da Ira. Os mesmos lembretes da rotação recomendada."
L["rm.sod.paladin.retribution.stacking.Name"] = "Retribuição, acúmulo de selos (SoD)"
L["rm.sod.paladin.retribution.stacking.Description"] = "Desativada por padrão; ative-a com a runa Alma do Porta-selos ou com o conjunto de seis peças que faz os selos persistirem (o Rotation Master não consegue ver nenhum dos dois). Mantém Selo de Comando e Selo do Martírio ativos, Tempestade Divina com três de Poder Sagrado, Golpe do Cruzado, Exorcismo, Ira Sagrada em Mortos-vivos e Demônios (em qualquer alvo com Poder Purificador gravado), Consagração, e Julgamento enquanto os dois selos estiverem ativos."
L["rm.sod.paladin.retribution.twist.Name"] = "Retribuição com alternância de selos (SoD)"
L["rm.sod.paladin.retribution.twist.Description"] = "Desativada por padrão; ative-a se você alterna selos com uma arma de duas mãos lenta. Troca entre Selo do Martírio e Selo de Comando nos últimos 0,4 segundos antes de cada golpe, não sugere nada no tempo de recarga global nos 1,9 segundos anteriores, julga enquanto os dois selos persistem e usa um preenchimento por golpe: Tempestade Divina com três de Poder Sagrado, Golpe do Cruzado, Exorcismo. Exige um temporizador de golpes e prática."
L["rm.sod.paladin.shockadin.Name"] = "Shockadin (SoD, simulador)"
L["rm.sod.paladin.shockadin.Description"] = "Desativada por padrão; ative-a se você causa dano com a árvore Sagrado. Ela se aplica com Sagrado como sua árvore principal e Choque e Pavor gravado. Selo do Martírio (senão Retidão), julgado quando estiver acabando, Choque Sagrado para manter Luz do Sol ativa ou com três de Poder Sagrado, Exorcismo e Golpe do Cruzado. Os mesmos lembretes da rotação integrada de Retribuição da Temporada da Descoberta."
L["rm.tbc.paladin.holy.Name"] = "Sagrado (Icy Veins & Wowhead)"
L["rm.tbc.paladin.holy.Description"] = "Cura para um Paladino Sagrado em grupo, no seu alvo amigável: Impor as Mãos ou Choque Sagrado para um alvo morrendo, Purificação (Purificar antes do 42), Choque Sagrado em movimento, Luz Sagrada para dano pesado, Luz Sagrada de grau 5 para manter Graça da Luz ativa, Clarão de Luz nos demais casos. Com um alvo hostil, mantém Julgamento da Sabedoria ativo. Lembretes: Aura de Concentração, Bênção de Sabedoria, Iluminação Divina e Favorecimento Divino. Um Paladino Sagrado jogando solo recebe uma rotação integrada de Retribuição."
L["rm.tbc.paladin.holy.wowhead.Name"] = "Sagrado (cura de tanque da Wowhead)"
L["rm.tbc.paladin.holy.wowhead.Description"] = "A cura de tanque em raide da Wowhead, uma alternativa à rotação integrada de Sagrado recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Luz Sagrada sempre que seu alvo tiver perdido um décimo da vida, Clarão de Luz só para pequenas perdas, com as mesmas emergências, purificações, Julgamento e lembretes da rotação integrada Sagrado combinada."
L["rm.tbc.paladin.protection.icyveins.Name"] = "Proteção (Icy Veins)"
L["rm.tbc.paladin.protection.icyveins.Description"] = "O tanque da Icy Veins, uma alternativa à rotação integrada de Proteção da Wowhead recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Julgamento do Cruzado quando ninguém o mantém, Retidão (Sabedoria em grupos), Consagração como principal fonte de ameaça, Julgamento, Escudo Sagrado e depois Escudo do Vingador e Martelo da Ira sempre que saírem do tempo de recarga. Os mesmos lembretes da variante Wowhead, sem Ira Vingativa."
L["rm.tbc.paladin.protection.wowhead.Name"] = "Proteção (Wowhead & simulador)"
L["rm.tbc.paladin.protection.wowhead.Description"] = "Tanque para a árvore Proteção ou qualquer Paladino com Fúria Íntegra ativa. Puxa com Escudo Sagrado, Escudo do Vingador e Julgamento; contra um alvo com golpes esmagadores (chefe mundial ou três ou mais níveis acima de você) Escudo Sagrado vem primeiro; depois Consagração, Exorcismo em Mortos-vivos e Demônios, Julgamento, Escudo Sagrado, Ira Sagrada em grupos de mortos-vivos, Escudo do Vingador exceto em alvos com golpes esmagadores. Selo da Sabedoria em grupos quando falta mana, Retidão nos demais casos. Lembretes: Fúria Íntegra, Aura de Devoção, Santuário (ou Reis, ou Sabedoria), Ira Vingativa, Impor as Mãos. Provocações e trocas de alvo ficam com você."
L["rm.tbc.paladin.retribution.icyveins.Name"] = "Retribuição (Icy Veins)"
L["rm.tbc.paladin.retribution.icyveins.Description"] = "A Retribuição da Icy Veins, uma alternativa à rotação integrada de Retribuição da Wowhead recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Julgamento do Cruzado uma vez por alvo, Selo da Retidão (Comando só com arma lenta, Sangue ou Mártir depois de aprendido), Golpe do Cruzado, Martelo da Ira e Julgamento sempre que saírem do tempo de recarga, Consagração em dois ou mais inimigos, Exorcismo em Mortos-vivos e Demônios e Choque Sagrado para quem evolui como Sagrado. Os mesmos lembretes da variante Wowhead."
L["rm.tbc.paladin.retribution.twist.Name"] = "Retribuição com alternância de selos"
L["rm.tbc.paladin.retribution.twist.Description"] = "Desativada por padrão; ative-a se você alterna selos (nível 64+, Selo de Comando e Sangue ou Mártir). Abre com Julgamento do Cruzado; depois, a cada golpe, ativa Selo de Comando (grau 1) cedo e troca para Sangue ou Mártir nos últimos 0,4 segundos, Golpe do Cruzado entre as alternâncias, julga apenas Sangue ou Mártir, Exorcismo e Consagração só como preenchimento, e mantém Sangue sem alternar abaixo de 12% de mana. Exige um temporizador de golpes confiável; a latência não é levada em conta."
L["rm.tbc.paladin.retribution.wowhead.Name"] = "Retribuição (Wowhead & simulador)"
L["rm.tbc.paladin.retribution.wowhead.Description"] = "Retribuição corpo a corpo do nível 1 ao 70, e o padrão para qualquer Paladino em que nenhuma outra rotação integrada se encaixe. Abre cada alvo com Julgamento da Sabedoria (mana baixa) ou do Cruzado, mantém seu melhor selo ativo (Sangue ou Mártir, Comando e depois Retidão), Golpe do Cruzado, julga apenas Retidão, Sangue ou Mártir (ou Comando em um alvo atordoado), Exorcismo em Mortos-vivos e Demônios, Consagração para três ou mais inimigos com mana de sobra. Martelo da Ira fica com você (a Wowhead o usa só em alvos em fuga). Lembretes: Aura de Santidade, Aura da Retribuição ou Aura de Devoção, uma Bênção em você mesmo, uma cura após a luta, Ira Vingativa. A alternância de selos é uma rotação integrada separada."
